/* Helpers that build per-layer arrays: each layer is {mixer, ffn}. */
function patternFromString(str) {
  // Nemotron-H style: one block per layer. M = Mamba-2, E = MoE, A = attention.
  return str.split("").map((ch) => ({
    mixer: ch === "M" ? "mamba" : ch === "A" ? "global" : null,
    ffn: ch === "E" ? "moe" : null,
  }));
}
function patternFromRules(n, isGlobal, isDense) {
  return Array.from({ length: n }, (_, i) => ({
    mixer: isGlobal(i) ? "global" : "swa",
    ffn: isDense(i) ? "dense" : "moe",
  }));
}

window.LAYER_KINDS = {
  global: { label: "Global attention", slot: 1 },
  mamba: { label: "Mamba-2", slot: 2 },
  moe: { label: "MoE FFN", slot: 3 },
  swa: { label: "Sliding-window attention", slot: 4 },
  dense: { label: "Dense FFN", slot: 5 },
  linear: { label: "Linear attention (KDA / Gated DeltaNet)", slot: 6 },
  sparse: { label: "Sparse global attention (top-k selected)", slot: 7 },
  conv: { label: "Gated short convolution", slot: 8 },
};

