      head: { v: "Untied, 1.34B each (report). Weightless RMSNorm on token embeddings; logits × 1/√(6656/256) = 0.196, then 20·tanh(z/20) (code)", s: "R+C" },
      mtp: { v: "No MTP. DFlash block-diffusion drafter: 5 layers, block 16, SWA 2048 everywhere, 32 Q / 8 KV heads, reads target layers 1, 13, 25, 37, 49", s: "R" },
