      encoders: { v: "Perception Encoder ViT-G/14, 1.8B, 50 layers, width 1536, native resolution on a 448-px grid. 2×2 pixel shuffle, 2-layer MLP adapter, then a bias-free linear and weightless RMSNorm. Up to 4,096 tokens per image. Frozen during training", s: "R" },
