    paramBreakdown: {
      s: "R",
      note: "Backbone versus Engram memory, from the report",
      parts: [
        { label: "Backbone", b: 552 },
        { label: "Engram n-gram memory", b: 196 },
      ],
    },
    highlights: [
      { t: "<b>Causal Encoder-Decoder.</b> Decoder layers do not build global KV from their own hidden states. The report's Eq. 1 gives each decoder layer its own projection of the encoder's final hidden state H<sub>L/2</sub> (after layer 19), but with CSA2 only the decoder's Full layer (L20) computes it; L21–39 reuse L20's stored KV (§2.3.1; kv_source_layer_ids). Prefill therefore only needs the 20 encoder layers. That nearly halves prefill compute, and is why active parameters are 8B at prefill and 16B at decode. Inspired by YOCO.", s: "R" },
      { t: "<b>CSA2: KV made in 4 layers, used in 38.</b> Each CSA2 layer is statically Full (make main KV and indices), Reindex (reuse KV, re-score with its own indexer query) or Reuse (reuse both). Only layers 2, 8, 14 and 20 produce main KV, and 8 layers produce indices. Every layer keeps its own query and SWA KV.", s: "R+C" },
      { t: "<b>FP4 KV cache.</b> Main KV is stored as E2M1 with one E4M3 scale per 16 channels and no second-level scale. After RMSNorm the 512-dim latent's entries are bounded by about √512 ≈ 22.6 (about 10 observed), far inside FP4's range. Trained with QAT in post-training, quantized after RoPE. SWA KV stays FP8.", s: "R" },
      { t: "<b>SWA Bounded Replay.</b> Rebuilding SWA state exactly would mean replaying L × 128 tokens. DeepSeek replays only the last 128 and accepts slightly approximate states. The persistent cache can then drop SWA KV entirely, about 1/8 of V4-Flash's footprint. The decoder replay is simulated in post-training.", s: "R" },
      { t: "<b>Engram memory.</b> 196B parameters of hashed n-gram embeddings (orders 2–4, 8 heads, ~16M-row prime-sized tables) at layers 1 and 14. Addresses depend only on the tokens, so lookups are prefetched from host memory over RDMA.", s: "R" },
      { t: "<b>Flat decode cost.</b> Going from 4K to 1M context raises single-token decode FLOPs by only about a quarter.", s: "R" },
    ],
