    tricks: [
      { cat: "Optimization & stability", name: "Head-wise Muon", t: "Query weights are split by head before the Muon update, so each head gets its own preconditioner (keys are one shared latent, so there is nothing to split). It beat vanilla Muon, as GLM 5 and Kimi K3 also found.", s: "R" },
      { cat: "Optimization & stability", name: "Sinkhorn-balanced updates for big tables", t: "Engram tables, the token embedding and the prediction head use Nesterov momentum followed by Sinkhorn balancing of rows and columns (K = 11), in place of Adam. It needs only a momentum buffer and outperformed Adam. LR is scaled by γ = 0.18 to match Adam's update size.", s: "R" },
      { cat: "Optimization & stability", name: "Muon RMS matching", t: "Muon updates are rescaled to RMS 0.18 so they reuse AdamW's learning rate. AdamW handles norms, biases and scales. Engram's learning rate is 5×.", s: "R" },
      { cat: "Long context", name: "Sparse attention from scratch", t: "Sparse attention is trained from the start at 64K sequence length, with no dense-attention warmup. Context goes to 1M at 34T tokens.", s: "R" },
      { cat: "Optimization & stability", name: "Per-modality expert balancing", t: "Text and image tokens keep separate aux-loss-free correction biases, updated from their own expert loads, so one modality's imbalance cannot hide behind the other's.", s: "R" },
      { cat: "Numerics", name: "Clamped SwiGLU", t: "Expert up-projections are clamped to ±10 and gates to ≤ 10 during training, to keep FP8 and FP4 activations in range.", s: "R+C" },
      { cat: "Quantization", name: "FP4 KV via post-training QAT", t: "Quantization-aware training extends FP4 from the indexer to the main KV cache. Quantizing after RoPE costs almost nothing versus before and is simpler at decode. SWA KV stays FP8 because it is quantization-sensitive.", s: "R" },
      { cat: "Data", name: "Implicit-duplication filtering", t: "Model-generated text with little new information (outputs of weaker models, poor machine translation) is filtered as implicit duplication that hurts over long training horizons.", s: "R" },
      { cat: "Data", name: "Packing and corpus merge", t: "Where a sample exists in both the text and multimodal pipelines, the multimodal version replaces it, giving a 7:1 text-to-multimodal token ratio. Best-fit packing keeps padding at or below 1e-4.", s: "R" },
      { cat: "Data", name: "Staged vision encoder", t: "DeepSeek-ViT is trained with SigLIP loss on about 47B image-text pairs at 224 px, then autoregressively on 236B tokens with a 4B MoE LLM. It stays frozen in backbone pretraining until LR decay, then trains jointly at a lower LR.", s: "R" },
      { cat: "Inference", name: "DSpark kept in sync", t: "The drafter is trained after pretraining with the backbone frozen. It keeps training alongside the policy in post-training, with no gradient into the backbone, so it accelerates RL and OPD rollouts too.", s: "R" },
      { cat: "RL", name: "Model merging between RL runs", t: "Checkpoints from RL runs on different scaffolds or configurations are merged to start the next run, aggregating parallel RL compute and improving token efficiency.", s: "R" },
      { cat: "RL", name: "Exponential effort penalty", t: "The prompt carries an effort b from 1 to 100. Rewards are centered within each (prompt, effort) subgroup, and the length penalty coefficient decays as k(b) = k0·exp(−(b − b_min)/τ), so higher effort is penalized less for length.", s: "R" },
      { cat: "RL", name: "Async RL hygiene", t: "Sample-level dispatch keeps rollout concurrency steady. Routing from multi-checkpoint samples is concatenated, not recomputed. Early short samples can be dropped to avoid length bias, and overly stale tokens are loss-masked.", s: "R" },
      { cat: "RL", name: "Containing reward hackers", t: "Agents exploited kernel and AppArmor bugs and package-mirror answer leaks. Per-sandbox AppArmor profiles and eBPF network policies block this, and an environment crash counts as a failed trajectory with a 'repercussion' signal.", s: "R" },
    ],
