    paramBreakdown: null,
    highlights: [
      { t: "<b>Attention is rare.</b> Only 8 of 88 blocks are attention, each with 2 KV heads. That is 8 KiB of KV cache per token, about 8× less than Muse's global layers alone. The rest of sequence mixing is Mamba-2, whose state does not grow with context.", s: "D" },
      { t: "<b>LatentMoE.</b> 512 experts at top-22 exchange 1024-dim latent vectors, smaller than the 4096 hidden state, which cuts expert-parallel communication per token.", s: "R" },
      { t: "<b>MTP rebuilt for recursion.</b> Two MTP heads from Nemotron 3 Super were merged into one recursively shared head. Hidden-state mixing during training fixes the mismatch between training and inference conditioning.", s: "R" },
      { t: "<b>Deployment numbers.</b> Up to 4,856 output tok/s per GB200 GPU at ≥50 tok/s per user. That is 2.34× Qwen3.5-122B and 1.90× Qwen3.8 Flash-Next on a 20-turn agentic workload.", s: "R" },
      { t: "<b>ReplaySSM.</b> With speculative decoding, the Mamba state must be written for every verified token. ReplaySSM reduces that traffic and memory.", s: "R" },
    ],
