    tricks: [
          {
                "cat": "Distillation",
                "name": "Skew reverse KL + CE on top-128 logits",
                "t": "Super distills from Ultra 3 Base with skew reverse KL (α = 0.1) on top-128 teacher logits. A sink token holds the probability mass outside the top 128, and the loss mixes 0.9 KL with 0.1 CE so rare tokens still get signal.",
                "s": "R"
          },
          {
                "cat": "Optimization & stability",
                "name": "Low-LR ramp to avoid drift",
                "t": "Distillation starts at the base model's minimum LR and ramps to only 10% of its original peak over 200B tokens, then decays. The MoE sequence load-balance coefficient is cut to 1e-5.",
                "s": "R"
          },
          {
                "cat": "Inference",
                "name": "MTP hidden-state mixing",
                "t": "During MTP training, step k is fed hidden states sampled from all earlier draft steps, not just step k−1. This matches inference-time drafting without the cost of multi-step test-time training.",
                "s": "R"
          },
          {
                "cat": "Inference",
                "name": "MTP boosting with a frozen backbone",
                "t": "After all post-training, only the MTP head is trained, by KD (LK loss) against the frozen model on on-policy rollouts. Acceptance length at T=1 goes from 3.79 to 4.61.",
                "s": "R"
          },
          {
                "cat": "Data",
                "name": "Loss-masked agent traces in mid-training",
                "t": "Mid-training uses natural SWE data with no chat template. Agent traces stay a small share (10%), with tool responses masked from the loss.",
                "s": "R"
          },
          {
                "cat": "Long context",
                "name": "Long-context recovery stage",
                "t": "Mid-training at 256K dropped RULER-1M from 79.9 to 33.5. A 9B-token recovery stage at 1M brought it back to 81.0.",
                "s": "R"
          },
          {
                "cat": "Data",
                "name": "Teacher choice and epochs",
                "t": "Reasoning traces under 5,000 tokens are dropped. Denser Kimi K3 traces kept improving over several epochs, where DeepSeek V4 Pro traces plateaued after one.",
                "s": "R"
          },
          {
                "cat": "Data",
                "name": "Budget control by truncation",
                "t": "A small fraction of SFT reasoning traces is truncated at random budgets, with the final answer kept and </think> masked, so inference-time budget control works.",
                "s": "R"
          },
          {
                "cat": "RL",
                "name": "Closing the train/inference gap",
                "t": "MoE router replay plus an FP32 LM head cut the KL between the training and inference engines by more than an order of magnitude.",
                "s": "R"
          },
          {
                "cat": "RL",
                "name": "Off-policy correction in MOPD",
                "t": "Rollouts can be one step stale. Tokens are importance-weighted, and weights outside [0.2, 5] are masked. Stage 2 uses a proximal teacher (α = 0.2) to bound negative advantages.",
                "s": "R"
          },
          {
                "cat": "RL",
                "name": "Ordering distillation by learning speed",
                "t": "MOPD stage 1 focuses on domains that improve fast and regress later (agentic, reasoning). Stage 2 focuses on slow domains (chat, vision) and anchors the rest to the stage-1 model.",
                "s": "R"
          },
          {
                "cat": "RL",
                "name": "Reward shaping for video RL",
                "t": "A malformed <think> block gets advantage −5, and correct answers get a soft length preference between 1K and 4K tokens. The router and vision tower are frozen.",
                "s": "R"
          },
          {
                "cat": "Post-training",
                "name": "Two-stage SFT for vision",
                "t": "The vision projector is warmed up first. Then a broad SFT stage and a smaller rebalancing stage follow, because learning vision and text together in one stage was hard.",
                "s": "R"
          },
          {
                "cat": "Quantization",
                "name": "Quantization-aware distillation",
                "t": "The NVFP4 recipe is followed by 200 iterations of QAD. The Mamba SSM cache is stored as FP16 with stochastic rounding. The appendix traces 'runaway loop' generations to FP4 experts in late layers.",
                "s": "R"
          },
          {
                "cat": "Data",
                "name": "LLM-judge decontamination",
                "t": "Training data is matched against 30 benchmarks with n-gram and embedding retrieval, and an LLM judge decides on paraphrases and translations. 20,671 samples were removed.",
                "s": "R"
          },
      {"cat": "Optimization & stability", "name": "Mamba-2 initialization", "t": "A_log is set to log(1…H), so head h decays at rate h. D (skip) starts at 1. dt_bias is the inverse softplus of a dt drawn log-uniformly from [0.001, 0.1] with a floor of 1e-4, so heads cover a range of timescales from the start.", "s": "C"},
      {"cat": "Optimization & stability", "name": "Depth-scaled output init", "t": "With rescale_prenorm_residual, the Mamba out_proj is initialized with Kaiming-uniform and then divided by √num_layers, so the 88 (or 52) residual adds start small.", "s": "C"},
      {"cat": "Numerics", "name": "FP32 where it matters", "t": "The expert-selection bias is kept in FP32, the RMSNorm weight multiply stays in FP32, and the Mamba SSM state cache defaults to FP32.", "s": "C"}
    ],
