    layersNote: "61 layers, all MoE (the first 3 hash-routed). compress_ratios in config.json: 128 (HCA) at layers 0–1 and every odd layer from 3, 4 (CSA) at every even layer from 2, so 30 CSA + 31 HCA. Every layer also has a 128-token sliding-window branch. The 62nd entry (0) is the MTP layer.",
    kv: { globalLayers: 61, swaLayers: 61, window: 128, kvHeads: 1, headDim: 512, stateBytes: 0, stateLabel: "", perTokenBytes: 30 * (576 / 4 + 64 / 4) + 31 * (576 / 128), fixedBytes: 61 * 128 * 576, perTokLabel: "compressed KV per token, FP8 + BF16 RoPE dims (30 CSA + 31 HCA layers)", fixedLabel: "SWA window, 61 layers × 128 tokens × 576 B", note: "Native cache format as described in the report: 448 FP8 dims + 64 BF16 RoPE dims per entry (576 B, scales ignored), FP4 indexer keys. Most other models on this page are shown in BF16." },
