      position: { v: "Partial RoPE on the last 64 of 512 dims, θ = 160k with YaRN (×16 from 64K) on compressed layers. Because K = V, RoPE at position −i is applied to the outputs so they carry relative, not absolute, position", s: "R+C" },
      attnExtras: { v: "Weightless RMS norm on each query head and a learned RMSNorm on KV entries, so no QK-Clip is needed. Learned per-head attention sink. CSA's compressor overlaps windows (each entry pools 2m tokens with softmax weights and learned positional biases). Lightning indexer: 64 heads × 128, ReLU scores, FP4 QK path after a Hadamard rotation. Grouped output projection: 16 groups × 1024 → 7168", s: "R+C" },
