    benchSource: { s: "B+C", t: "Qwen3.8-Flash-Next launch blog (tier 2; the model card repeats it). Coding at 256K context, temperature 1.0, top-p 0.95: Claude Code for SWE-bench Pro and NL2Repo, mini-SWE-agent for SWE-bench Multilingual, best of the two for DeepSWE." },
